#pragma once
// Native Windows language selection: deliberately independent of .NET.
static int NativeLanguage(){
 wchar_t folder[MAX_PATH]={};std::string pref;
 if(SUCCEEDED(SHGetFolderPathW(NULL,CSIDL_LOCAL_APPDATA,NULL,SHGFP_TYPE_CURRENT,folder))){
  std::wstring path=std::wstring(folder)+L"\\RichsRetro\\RRFFPreferences\\language.txt";
  HANDLE file=CreateFileW(path.c_str(),GENERIC_READ,FILE_SHARE_READ|FILE_SHARE_WRITE,NULL,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);
  if(file!=INVALID_HANDLE_VALUE){char bytes[65]={};DWORD count=0;if(ReadFile(file,bytes,64,&count,NULL)&&count<64){pref.assign(bytes,count);if(pref.size()>=3&&(unsigned char)pref[0]==0xef&&(unsigned char)pref[1]==0xbb&&(unsigned char)pref[2]==0xbf)pref.erase(0,3);while(!pref.empty()&&(pref.back()=='\r'||pref.back()=='\n'||pref.back()==' '))pref.pop_back();}CloseHandle(file);}
 }
 const char* codes[]={"en","de","es","fr","it","pt"};for(int i=0;i<6;i++)if(pref==codes[i])return i;
 switch(PRIMARYLANGID(GetUserDefaultUILanguage())){case LANG_GERMAN:return 1;case LANG_SPANISH:return 2;case LANG_FRENCH:return 3;case LANG_ITALIAN:return 4;case LANG_PORTUGUESE:return 5;default:return 0;}
}
