static int NativeMessageBox(HWND owner,const wchar_t* text,const wchar_t* title,UINT flags){
 TASKDIALOG_BUTTON buttons[2];const bool yesNo=(flags&MB_TYPEMASK)==MB_YESNO;
 buttons[0]={yesNo?IDYES:IDOK,N(yesNo?L"Yes":L"OK")};buttons[1]={IDNO,N(L"No")};
 TASKDIALOGCONFIG dialog={};dialog.cbSize=sizeof(dialog);dialog.hwndParent=owner;dialog.dwFlags=TDF_ALLOW_DIALOG_CANCELLATION|TDF_SIZE_TO_CONTENT;dialog.pszWindowTitle=title;dialog.pszContent=text;dialog.pButtons=buttons;dialog.cButtons=yesNo?2:1;dialog.nDefaultButton=yesNo?((flags&MB_DEFMASK)==MB_DEFBUTTON2?IDNO:IDYES):IDOK;dialog.cxWidth=440;
 switch(flags&MB_ICONMASK){case MB_ICONERROR:dialog.pszMainIcon=TD_ERROR_ICON;break;case MB_ICONWARNING:dialog.pszMainIcon=TD_WARNING_ICON;break;case MB_ICONINFORMATION:case MB_ICONQUESTION:dialog.pszMainIcon=TD_INFORMATION_ICON;break;}
 int result=IDCANCEL;if(SUCCEEDED(TaskDialogIndirect(&dialog,&result,NULL,NULL)))return result;
 // Fallback for an unavailable common-controls dialog; decisions stay unchanged.
 return MessageBoxExW(owner,text,title,flags,GetUserDefaultUILanguage());
}
